Rules.InvariantScript:
false
// INERT ON PURPOSE. Same reason as scrHome: CLAUDE.md
// open question 2 is unresolved and colAudit is the wrong
// shape. Do NOT bind this to colAudit.

Table(
    {
        Id: 1,
        Title: "Getting Started",
        Blurb: "Learn the basics"
    },
    {
        Id: 2,
        Title: "Creating Requests",
        Blurb: "How to create new requests"
    },
    {
        Id: 3,
        Title: "Managing Tasks",
        Blurb: "Complete and track tasks"
    },
    {
        Id: 4,
        Title: "Workflow Management",
        Blurb: "Edit and manage workflows"
    },
    {
        Id: 5,
        Title: "Reports",
        Blurb: "Understanding analytics"
    },
    {
        Id: 6,
        Title: "Admin Guide",
        Blurb: "Configuration settings"
    }
)

Filter(
    Table(
        {
            Id: 1,
            Question: "How do I create a new request?",
            Answer: "Click the New Request button on the dashboard or All Requests page. Fill in the required fields and select a category to start the workflow."
        },
        {
            Id: 2,
            Question: "How do I reroute a task?" & If(nfIsFullVersion, "", " (Full version)"),
            Answer: "Open the request details, find the task you want to reroute, and click the Reroute button. Select the new assignee and add a reason." & If(nfIsFullVersion, "", " " & nfGateSuffix)
        },
        {
            Id: 3,
            Question: "What do the phase indicators mean?",
            Answer: "Phase indicators show workflow progress. Blue segments are completed, grey are pending. The numbers show current phase versus total phases."
        },
        {
            Id: 4,
            Question: "How do I suspend a workflow?" & If(nfIsFullVersion, "", " (Full version)"),
            Answer: "Open the request details and click Suspend Workflow in the actions area. Only Request Admins and POCs can suspend workflows." & If(nfIsFullVersion, "", " " & nfGateSuffix)
        },
        {
            Id: 5,
            Question: "How do I edit the workflow structure?" & If(nfIsFullVersion, "", " (Full version)"),
            Answer: "Click Edit Workflow on the details page. You can add or remove phases, add or remove workers, and change the worker order." & If(nfIsFullVersion, "", " " & nfGateSuffix)
        }
    ),
    IsBlank(Trim(txtHlpSearch.Text))
        || Trim(txtHlpSearch.Text) in Question
        || Trim(txtHlpSearch.Text) in Answer
)

UpdateContext(
    {
        locHlpFaq:
            If(
                locHlpFaq = ThisItem.Id,
                0,
                ThisItem.Id
            )
    }
)

Table(
    {Icon: "home", Label: "Home", Badge: 0},
    {Icon: "search", Label: "Explore", Badge: 0},
    {Icon: "bell", Label: "Alerts", Badge: 3},
    {Icon: "user", Label: "Profile", Badge: 0}
)

ForAll(
    Sequence(CountRows(cmpBottomNavigation.Items)),
    {
        Index: Value,
        Icon: Index(cmpBottomNavigation.Items, Value).Icon,
        Label: Index(cmpBottomNavigation.Items, Value).Label,
        Badge: Coalesce(Index(cmpBottomNavigation.Items, Value).Badge, 0)
    }
)

ForAll(
    nfNavMobile As m,
    {
        Icon: m.Icon,
        Label: m.Label,
        Badge: If(
            m.ID = 2,
            nfMyOpenCount,
            0
        )
    }
)

Filter(
  cmpSidebar.Items,
  Visible &&
  (
    // section rows
    (IsSection && CountRows(Filter(cmpSidebar.Items, !IsSection && Visible)) > 0) ||
    // root-level items
    (!IsSection && ParentID = -1) ||
    // child items — only when parent expanded AND nav expanded
    (!IsSection && ParentID > -1 && ParentID in colNavExpanded.ID && _cmpNavIsExpanded)
  )
)

If(
  !Coalesce(ThisItem.IsSection, false),
  If(
    CountRows(Filter(cmpSidebar.Items, ParentID = ThisItem.ID)) > 0,
    // parent item — toggle expand
    If(
      ThisItem.ID in colNavExpanded.ID,
      RemoveIf(colNavExpanded, ID = ThisItem.ID),
      Collect(colNavExpanded, {ID: ThisItem.ID})
    ),
    // leaf item — select and fire event
    Set(_cmpNavSelID, ThisItem.ID);
    cmpSidebar.OnNavSelect()
  )
)

Patch(
    colUserPrefs,
    First(colUserPrefs),
    { ThemeName: If(nfIsDark, "Light", "Dark") }
);
ClearCollect(
    colUserPrefs,
    Filter(colUserPrefs, UserEmail = Lower(nfUserEmail))
)

Set(
    _fabSelectedSD,
    {
        Icon: ThisItem.Icon,
        Label: ThisItem.Label,
        Color: ThisItem.Color
    }
);
 Set(_fabOpen, false);
 cmpFloatingActionButton.OnSpeedDialSelect()

With(
    {
        _fabSize: Switch(
            Self.Size,
            "small", 40,
            "regular", 56,
            "large", 72,
            56
        )
    },
    If(
        _fabOpen && CountRows(Self.SpeedDialItems) > 0,
        _fabSize + 12 + CountRows(Self.SpeedDialItems) * Self.ItemSize,
        _fabSize
    )
)
